"use client";

import { useEffect, useRef, type CSSProperties } from "react";
import { useTheme } from "next-themes";
import { cn } from "@/lib/utils";

type HeroTheme = "dark" | "light";
type HeroHandle = { setTheme: (theme: HeroTheme) => void; destroy: () => void };
type NetworkInfo = { connection?: { saveData?: boolean } };

// A self-contained three.js bundle, loaded at runtime so three.js stays out of the main bundle
// and the first paint. It handles resizing, off-screen pausing and reduced motion itself.
// Generated by the video-generator project's /hero skill, which writes public/hero/hero.js.
const HERO_BUNDLE_URL = "/hero/hero.js";

const toHeroTheme = (theme?: string): HeroTheme => (theme === "light" ? "light" : "dark");

/**
 * Live animated backdrop for the hero. Purely decorative: if it can't run, the page behind it stays.
 * `textEdge` is the distance from the page centre to the right edge of the header's text; the
 * scene is masked to stay clear of it. Omit it where the layout already keeps text clear.
 */
export function HeroScene({ className, textEdge }: { className?: string; textEdge?: string }) {
  const containerRef = useRef<HTMLDivElement>(null);
  const handleRef = useRef<HeroHandle | null>(null);
  const { resolvedTheme } = useTheme();
  const themeRef = useRef<HeroTheme>(toHeroTheme(resolvedTheme));

  useEffect(() => {
    themeRef.current = toHeroTheme(resolvedTheme);
    handleRef.current?.setTheme(themeRef.current);
  }, [resolvedTheme]);

  useEffect(() => {
    if ((navigator as NetworkInfo).connection?.saveData) return;

    let cancelled = false;
    import(/* turbopackIgnore: true */ /* webpackIgnore: true */ HERO_BUNDLE_URL)
      .then(({ mount }) => {
        if (cancelled || !containerRef.current) return;
        handleRef.current = mount(containerRef.current, { theme: themeRef.current });
      })
      .catch(() => {});

    return () => {
      cancelled = true;
      handleRef.current?.destroy();
      handleRef.current = null;
    };
  }, []);

  return (
    <div
      ref={containerRef}
      className={cn(
        "pointer-events-none absolute inset-0 -z-10",
        textEdge && "hero-scene-clear",
        className,
      )}
      style={textEdge ? ({ "--hero-text-edge": textEdge } as CSSProperties) : undefined}
      aria-hidden="true"
    />
  );
}
